def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Detect the small diamond motifs: a center cell with two diagonal
    # neighbors above and below. Extend between matching motifs.
    motifs = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 2 and
                grid[r-1][c-1] == 2 and grid[r-1][c+1] == 2 and
                grid[r+1][c-1] == 2 and grid[r+1][c+1] == 2):
                motifs.append((r, c))

    # Join motif centers that share a row or column, filling only the gap
    # between their outermost 2-cells.
    for i, (r1, c1) in enumerate(motifs):
        for r2, c2 in motifs[i+1:]:
            if r1 == r2 and abs(c2-c1) > 2:
                lo, hi = sorted((c1, c2))
                for c in range(lo+1, hi):
                    if grid[r1][c] == 0:
                        out[r1][c] = 1
            elif c1 == c2 and abs(r2-r1) > 2:
                lo, hi = sorted((r1, r2))
                for r in range(lo+1, hi):
                    if grid[r][c1] == 0:
                        out[r][c1] = 1

    # Also extend between facing 2-cell endpoints of these motifs.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == 2]
        for a, b in zip(cols, cols[1:]):
            if 2 <= b-a <= 6 and any((mr == r and mc in (a, b)) for mr, mc in motifs):
                for c in range(a+1, b):
                    if grid[r][c] == 0:
                        out[r][c] = 1
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == 2]
        for a, b in zip(rows, rows[1:]):
            if 2 <= b-a <= 4 and any((mc == c and mr in (a, b)) for mr, mc in motifs):
                for r in range(a+1, b):
                    if grid[r][c] == 0:
                        out[r][c] = 1

    return out

