def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    out = [[0] * w for _ in range(h)]

    # Tile the shape with 2x2 squares and three-cell L shapes.
    # Prefer squares, then use L pieces for the remaining cells.
    pieces = []
    remaining = set(occupied)
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r,c), (r+1,c), (r,c+1), (r+1,c+1)}
            if square <= remaining:
                pieces.append((1, square))
                remaining -= square

    # L triomino colors are determined by the missing corner of their 2x2 box.
    corner_color = {
        (1, 1): 2,  # missing lower-right
        (1, 0): 3,  # missing lower-left
        (0, 1): 4,  # missing upper-right
        (0, 0): 2,  # missing upper-left
    }
    while remaining:
        found = None
        for r in range(h - 1):
            for c in range(w - 1):
                box = {(r,c), (r+1,c), (r,c+1), (r+1,c+1)}
                tri = box & remaining
                if len(tri) == 3:
                    missing = next(iter(box - tri))
                    found = (corner_color[(missing[0]-r, missing[1]-c)], tri)
                    break
            if found:
                break
        if found:
            color, cells = found
            pieces.append((color, cells))
            remaining -= cells
        else:
            cell = min(remaining)
            pieces.append((2, {cell}))
            remaining.remove(cell)

    for color, cells in pieces:
        for r, c in cells:
            out[r][c] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    best_color = grid[0][0]
    best_size = 0

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            size = 0
            while stack:
                y, x = stack.pop()
                size += 1
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if size > best_size:
                best_size = size
                best_color = color

    return [[best_color] * 3 for _ in range(3)]

