def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Identify vertical guide columns from the short vertical objects at the bottom.
    guides = [c for c in range(w)
              if any(grid[r][c] for r in range(h - 2, h))]

    for c in guides:
        bars = []
        for r in range(h):
            if grid[r][c] != 0:
                continue
            left = next((grid[r][x] for x in range(c - 1, -1, -1)
                         if grid[r][x] != 0), 0)
            right = next((grid[r][x] for x in range(c + 1, w)
                          if grid[r][x] != 0), 0)
            if left or right:
                color = left if left else right
                bars.append((r, color))
                out[r][c] = color

        # Between successive horizontal stripes, the gap column is filled
        # with the color of the stripe below; above the first stripe, use its color.
        bars.sort()
        for i, (r, color) in enumerate(bars):
            top = 0 if i == 0 else bars[i - 1][0] + 1
            for rr in range(top, r):
                if out[rr][c] == 0:
                    out[rr][c] = color

    return out

def transform(grid):
