def transform(grid):
    h, w = len(grid), len(grid[0])
    bars = []
    for r, row in enumerate(grid):
        vals = set(row) - {0}
        if vals and len(vals) == 1 and len(vals) == w:
            bars.append((r, row[0]))
    if not bars:
        return [row[:] for row in grid]

    period = len(bars)
    seq = [0] * period
    for r, color in bars:
