def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each diagonal marker gives the color assigned to that diagonal in the
    # repeating pattern. Sort the marked diagonals and repeat their colors.
    diagonals = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                diagonals.setdefault(r + c, []).append(grid[r][c])

    seq = []
    for k in sorted(diagonals):
        # A diagonal may contain repeated markers of the same color.
        vals = diagonals[k]
        seq.append(max(set(vals), key=vals.count))

    if not seq:
        return grid

    start = min(diagonals)
    return [[seq[(r + c - start) % len(seq)] for c in range(w)]
            for r in range(h)]

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each solid nonzero row contributes its color to the repeating sequence.
