def transform(grid):
    h, w = len(grid), len(grid[0])
    # The diagonal marks encode a repeating sequence, read from the
    # grid's outer edge toward the opposite edge.
    bands = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                bands[r + c] = grid[r][c]

    # Collapse repeated marks belonging to the same diagonal stripe.
    seq = [bands[k] for k in sorted(bands)]
    if not seq:
        return [row[:] for row in grid]
    return [[seq[(r - c) % len(seq)] for c in range(w)] for r in range(h)]

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Get the palette from a nonzero line repeated on parallel lines.
    palette = None
    for r in range(h):
        seq = [grid[r][c] for c in range(w) if grid[r][c]]
        if len(set(seq)) > 1 and sum(
            [grid[rr][c] for c in range(w) if grid[rr][c]] == seq
            for rr in range(h)
        ) >= 2:
            palette = seq
            break
    if palette is None:
        for c in range(w):
            seq = [grid[r][c] for r in range(h) if grid[r][c]]
            if len(set(seq)) > 1 and sum(
                [grid[r][cc] for r in range(h) if grid[r][cc]] == seq
                for cc in range(w)
            ) >= 2:
                palette = seq
                break

    # Extract the largest connected component of color 1 as the template.
    remaining = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1}
    comps = []
    while remaining:
        seed = remaining.pop()
        comp = {seed}
        todo = [seed]
        while todo:
            r, c = todo.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in remaining:
                    remaining.remove(q)
                    comp.add(q)
                    todo.append(q)
        comps.append(comp)
    shape_pts = max(comps, key=len)
    r0, r1 = min(r for r,c in shape_pts), max(r for r,c in shape_pts)
    c0 = min(c for r,c in shape_pts)
    dh = r1-r0+1
    shape = [(r-r0,c-c0) for r,c in shape_pts]

    if palette is None:
        return grid
    first = r0 - palette.index(1)*dh
    out = [[0]*w for _ in range(h)]
    for i, color in enumerate(palette):
        for dr, dc in shape:
            rr, cc = first+i*dh+dr, c0+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []

    # Find solid 3x3 monochrome blocks.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[i][j] == color
                             for i in range(r, r + 3)
                             for j in range(c, c + 3)):
                blocks.append((r + 1, c + 1, color))

    # Extend each block's central row and column. Conflicting extensions
    # leave a blank at their intersection; preserve original nonzero cells.
    lines = {}
    for r, c, color in blocks:
        for j in range(w):
            if grid[r][j] == 0:
                lines.setdefault((r, j), set()).add(color)
        for i in range(h):
            if grid[i][c] == 0:
                lines.setdefault((i, c), set()).add(color)

    for (r, c), colors in lines.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out

