def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The masked cells belong to the repeating diagonal sequence in the
    # patterned interior. Infer its period and phase-to-color mapping from
    # the unmasked cells.
    best = None
    for period in range(2, 11):
        counts = {}
        for r in range(8, h):
            for c in range(3, w):
                v = grid[r][c]
                if v != 0:
                    key = (r + c) % period
                    counts.setdefault(key, {})
                    counts[key][v] = counts[key].get(v, 0) + 1
        score = sum(max(d.values()) for d in counts.values())
        if best is None or score > best[0]:
            best = (score, period, counts)

    _, period, counts = best
    mapping = {k: max(d, key=d.get) for k, d in counts.items()}

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and r >= 3 and c >= 3:
                if (r + c) % period in mapping:
                    out[r][c] = mapping[(r + c) % period]
    return out

def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        # Recolor the trailing segment when a row begins with a run of
        # the same color as the full-width stripe.
        first = row[0]
