def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import deque

    # Find the connected component of the non-background marker color.
    counts = {}
    for row in grid:
        for v in row:
            if v not in (0, 5, 9):
                counts[v] = counts.get(v, 0) + 1
    if not counts:
        return [r[:] for r in grid]
    color = max(counts, key=counts.get)
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    shape = {(r-r0, c-c0) for r, c in cells}
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1

    # Repeat the marker shape at each location where its footprint is entirely
    # composed of the background colors.
    out = [row[:] for row in grid]
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] != color for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v not in (0, 9)}
    color = next(iter(colors))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    minr, maxr = min(r for r, c in pts), max(r for r, c in pts)
    minc, maxc = min(c for r, c in pts), max(c for r, c in pts)
