                    seen.add((nr,nc))
                    stack.append((nr,nc))
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Fill the diagonal segment between each diagonally aligned pair of 1s.
    diagonal_segments = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if r2 != r1 and abs(r2 - r1) == abs(c2 - c1):
                sr = 1 if r2 > r1 else -1
                sc = 1 if c2 > c1 else -1
                cells = [(r1 + k * sr, c1 + k * sc)
                         for k in range(abs(r2 - r1) + 1)]
                diagonal_segments.append(cells)
                for r, c in cells:
                    if grid[r][c] != 6:
                        out[r][c] = 1

    # A 6 on a 1-connection extends along its own NW-SE diagonal.
    extend = set()
    for r, c in sixes:
        if any((r, c) in cells for cells in diagonal_segments):
            rr, cc = r, c
            while rr > 0 and cc > 0:
                rr -= 1
                cc -= 1
            while rr < h and cc < w:
                extend.add((rr, cc))
                rr += 1
                cc += 1

    # Aligned 6s also define a full diagonal line.
    for i, (r1, c1) in enumerate(sixes):
        for r2, c2 in sixes[i + 1:]:
